{
  "implementation": "def solve(case):
    # Extract fields
    nodes = case['nodes']
    core_distance = case['core_distance']
    distances = case['distances']

    # Validate all nodes have core distance
    for node in nodes:
        if node not in core_distance:
            raise ValueError(f"Missing core distance for node {node}")

    # Build edges with mutual reachability weight
    edges = []
    for a, b, dist in distances:
        # Ensure canonical ordering: a < b lexicographically
        if a < b:
            u, v = a, b
        else:
            u, v = b, a
        weight = max(core_distance[u], core_distance[v], dist)
        edges.append((weight, u, v))

    # Sort edges by (weight, u, v)
    edges.sort(key=lambda x: (x[0], x[1], x[2]))

    # Union-Find
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True

    mst_edges = []
    total_weight = 0.0
    for weight, u, v in edges:
        if union(u, v):
            mst_edges.append([u, v, weight])
            total_weight += weight
            if len(mst_edges) == len(nodes) - 1:
                break

    if len(mst_edges) != len(nodes) - 1:
        raise ValueError("Graph is disconnected; MST not possible")

    return {
        "mst_edges": mst_edges,
        "total_weight": total_weight
    }"
}
